<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Availability</title><link rel="stylesheet" href="assets/css/style_delivery.css"></head><body><?php require APP_PATH . '/views/layouts/header_sidebar_delivery.php'; ?><main class="main"><section class="delivery-dashboard-heading"><p class="eyebrow">Work status</p><h1>Availability</h1><p>Set your status so administrators can assign work accurately.</p></section><section class="delivery-panel"><?php if ($message): ?><p class="success-message"><?php echo $message; ?></p><?php endif; ?><form method="post" class="delivery-form-grid"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrfToken); ?>"><label class="full-width">Current availability<select name="availability"><option value="Available" <?php echo $current === 'Available' ? 'selected' : ''; ?>>Available — ready for an assignment</option><option value="Busy" <?php echo $current === 'Busy' ? 'selected' : ''; ?>>Busy — currently handling work</option><option value="Offline" <?php echo $current === 'Offline' ? 'selected' : ''; ?>>Offline — do not assign work</option></select></label><div class="full-width"><button class="request-accept" type="submit">Save Availability</button></div></form></section></main></body></html>
